import {execute,methodology} from './core/api.mjs';
import {fields} from './core/definitions.mjs';
import {registerTools} from './core/tools.mjs';
const form=document.querySelector('[data-calculator]');
const spec=form?JSON.parse(document.querySelector('#calculator-config').textContent):null;
const sample=form?JSON.parse(document.querySelector('#calculator-example').textContent):null;
const currency=new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN',maximumFractionDigits:6});
const money=value=>currency.format(Number(value));
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
const normal=v=>v.trim().replace(/[\s\u00a0]/g,'').replace(',','.');
const safeNumber=v=>v.trim()===''?undefined:Number(normal(v));
let current=null,baseline=null,accountIndex=1;
function metrics(r){if(r.metrics)return r.metrics;
 const m=(label,value)=>({label,value,unit:'PLN'});
 if(r.taxBasePln!==undefined)return [m('Podstawa po zwolnieniach',r.taxBasePln),m('Kwota arytmetyczna przed końcowym zaokrągleniem',r.taxBeforeFinalRoundingPln),m('Zwolnienie S',r.exemptions.S),m('Zwolnienie I',r.exemptions.I)];
 if(r.sellNowNetPln!==undefined)return [m('Sprzedaż teraz i OKI — kapitał',r.sellNowNetPln),m('Stary portfel i nowe wpłaty do OKI',r.keepPortfolioNetPln),m('Sprzedaż teraz minus zachowanie portfela',r.differencePln),m('Modelowy podatek przy sprzedaży teraz',r.upfrontTaxPln)];
 if(r.oki)return [m('OKI po modelowych opłatach i podatkach',r.oki.balancePln),m('Zwykły rachunek po końcowej sprzedaży',r.ordinary.netBalancePln),m('OKI minus zwykły rachunek',r.differencePln),m('Wpłacony kapitał',r.contributionsPln),m('Suma modelowych podatków OKI',r.oki.taxPln),m('Podatek zwykłego rachunku na końcu',r.ordinary.taxPln)];
 if(r.withFees)return [m('Kapitał z opłatami',r.withFees.balancePln),m('Kapitał bez tych opłat',r.withoutFees.balancePln),m('Suma pobranych opłat',r.withFees.feesPln),m('Wpływ opłat wraz z utraconym wzrostem',r.costImpactPln)];
 return [m('Kapitał na końcu, bez podatków',r.balancePln),m('Wpłacony kapitał',r.contributionsPln),m('Pobrane opłaty',r.feesPln)];
}
function unitValue(m){return m.unit==='PLN'?money(m.value):Number(m.value).toLocaleString('pl-PL',{maximumFractionDigits:6})+(m.unit==='percent'?'%':m.unit==='years'?' lat':'');}
const columnNames={year:'Rok',month:'Miesiąc',balancePln:'Kapitał na koniec',averagePln:'Średnia modelowa',contributionsPln:'Wpłacono łącznie',withdrawalsPln:'Wypłacono łącznie',feesPln:'Opłaty',taxPln:'Podatek modelowy',variant:'Wariant',okiNetPln:'OKI nominalnie',ordinaryNetPln:'Zwykły netto',realOkiNetPln:'OKI realnie',differencePln:'Różnica',okiPln:'OKI netto',ordinaryPln:'Zwykły netto'};
function table(rows){const wrap=el('div',undefined,'table-wrap'),t=el('table'),head=el('thead'),tr=el('tr');const keys=Object.keys(rows[0]);for(const key of keys){const th=el('th',columnNames[key]??key);th.scope='col';tr.append(th);}head.append(tr);t.append(el('caption','Wartości modelowe; jednostki PLN, jeśli nie wskazano inaczej.'),head);const body=el('tbody');for(const row of rows){const r=el('tr');for(const k of keys)r.append(el('td',k.endsWith('Pln')?money(row[k]):String(row[k])));body.append(r);}t.append(body);wrap.append(t);return wrap;}
function chart(rows){if(rows.length<2||!rows.every(r=>r.balancePln!==undefined&&r.year!==undefined))return null;const vals=rows.map(r=>Number(r.balancePln)),max=Math.max(...vals,1),w=640,h=190;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${w} ${h+35}`);svg.setAttribute('role','img');svg.setAttribute('aria-label','Przebieg modelowego kapitału; dokładne wartości są w tabeli rocznej.');svg.classList.add('chart');const poly=document.createElementNS(svg.namespaceURI,'polyline');poly.setAttribute('points',vals.map((v,i)=>`${20+i*(w-40)/(vals.length-1)},${h-10-v/max*(h-30)}`).join(' '));poly.setAttribute('fill','none');poly.setAttribute('stroke','currentColor');poly.setAttribute('stroke-width','3');svg.append(poly);for(const [x,text] of [[20,String(rows[0].year)],[w-65,String(rows.at(-1).year)]]){const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x',x);label.setAttribute('y',h+20);label.textContent=text;svg.append(label);}return svg;}
function render(r){
 const out=document.querySelector('#result');out.replaceChildren();out.hidden=false;current=r;document.querySelector('#comparison-result').hidden=true;
 const computable=['ok','insufficient_funds'].includes(r.status);
 out.append(el('p',computable?'WYNIK MODELU':'SPRAWDŹ DANE I ZAKRES','eyebrow'),el('h2',computable?'Twój scenariusz w liczbach':r.status==='no_solution'?'Brak rozwiązania w zadanym zakresie':'Nie obliczono wyniku'));
 if(r.message)out.append(el('p',r.message,'note'));
 if(!computable){if(r.field)out.append(el('p','Pole: '+r.field+'. Brak danych nie oznacza zera.'));current=null;return;}
 if(r.status==='insufficient_funds')out.append(el('p','Pokazano tylko rzeczywiście pokryte wypłaty w modelu; plan nie został w pełni zrealizowany.'));
 const grid=el('div',undefined,'metrics');for(const m of metrics(r)){const box=el('div',undefined,'metric');box.append(el('span',m.label),el('strong',unitValue(m)));grid.append(box);}out.append(grid);
 const rows=r.rows??r.oki?.rows??r.withFees?.rows;
 if(rows?.length){const plot=chart(rows);if(plot)out.append(plot);const d=el('details');d.open=document.body.dataset.brand==='zrozumoki';d.append(el('summary','Tabela modelu'),table(rows));out.append(d);}
 if(r.crossings){out.append(el('h3','Zmiany znaku różnicy'));out.append(el('p',r.crossings.length?r.crossings.map(c=>`${c.fromYear}–${c.toYear}`).join(', '):'Brak zmiany znaku na sprawdzonych końcach lat. To nie dowodzi przewagi poza zakresem.'));}
 if(r.exhaustedMonthOriginal!==undefined)out.append(el('p',`Pierwsza niepokryta w pełni wypłata: kolejność podana ${r.exhaustedMonthOriginal??'brak'}, odwrócona ${r.exhaustedMonthReversed??'brak'}. Numer miesiąca 1 oznacza styczeń 2027.`));
 out.append(el('h3','Założenia i ograniczenia'));const list=el('ul');for(const s of r.limitations??[])list.append(el('li',s));out.append(list);
 const details=el('details',undefined,'raw-data');details.append(el('summary','Dane wejściowe i pełny wynik'),el('pre',JSON.stringify(r,null,2)));out.append(details);
 const printed=el('div',undefined,'print-only');printed.append(el('h3','Dane wejściowe'));for(const [key,value] of Object.entries(r.input??{})){let display;if(Array.isArray(value))display=JSON.stringify(value.length>40?{count:value.length,first:value[0],last:value.at(-1)}:value);else if(value&&typeof value==='object')display=JSON.stringify(value);else display=String(value);printed.append(el('p',`${fields[key]?.label??key}: ${display}`));}out.append(printed);
 out.append(el('p',`Silnik ${r.calculationVersion} · reguły ${r.rulesVersion} · sprawdzono ${r.checkedAt}`,'muted'));
 const actions=el('div',undefined,'actions');for(const [label,fn] of [['Drukuj wynik',()=>window.print()],['Zapisz plan JSON',()=>downloadPlan(r)],['Zapamiętaj jako wariant A',()=>{baseline=structuredClone(r);announce('Zapamiętano wariant A w pamięci tej strony. Zmień dane i oblicz wariant B.');}]]){const b=el('button',label,'secondary');b.type='button';b.addEventListener('click',fn);actions.append(b);}out.append(actions);
 if(baseline){const panel=document.querySelector('#comparison-result');panel.replaceChildren(el('h2','Wariant B wobec zapamiętanego A'));const left=metrics(baseline),right=metrics(r),rows=right.filter(m=>left.some(a=>a.label===m.label&&a.unit===m.unit)).map(m=>({variant:m.label,valueAPln:left.find(a=>a.label===m.label).value,valueBPln:m.value,differencePln:(Number(m.value)-Number(left.find(a=>a.label===m.label).value)).toFixed(2)}));if(right.some(m=>m.unit!=='PLN'))panel.append(el('p','Zestawienie A/B dla tego narzędzia odczytaj z zapisanych wyników — różne jednostki nie są sumowane.'));else if(rows.length)panel.append(table(rows));panel.append(el('p','To porównanie dwóch własnych modeli. Sprawdź, które dane zmieniłeś i czy zakres pozostał zgodny.'));panel.hidden=false;}
}
function announce(text){document.querySelector('#example-state').textContent=text;}
function downloadPlan(r){const payload={format:'oki-plan',version:methodology().calculationVersion,calculatorId:spec.id,tool:spec.tool,input:r.input,result:r};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=el('a');a.href=u;a.download=`plan-oki-${spec.slug}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function parseList(key,text){const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(key==='annualReturnsPercent')return lines.map(s=>safeNumber(s));if(key==='deposits')return lines.map(line=>{const parts=line.split(';');if(parts.length!==2)throw Error('Każda wpłata: miesiąc; kwota.');return {month:safeNumber(parts[0]),amountPln:normal(parts[1])};});if(key==='rows')return lines.map(line=>{const parts=line.split(';');if(parts.length!==4)throw Error('Każdy dzień: data; wartość; wpłata; wypłata.');return {date:parts[0].trim(),valuePln:normal(parts[1]),depositPln:normal(parts[2]),withdrawalPln:normal(parts[3])};});throw Error('Nieobsługiwana lista.');}
function readInput(){if(spec.id==='S08')return {taxYear:2027,accounts:[...form.querySelectorAll('[data-account]')].map(box=>Object.fromEntries([...box.querySelectorAll('input')].map(i=>[i.dataset.field,normal(i.value)])))};
 const data={...spec.preset};for(const key of spec.fields){const input=form.elements.namedItem(key),f=fields[key],v=input.value;data[key]=f.kind==='money'?normal(v):['number','integer'].includes(f.kind)?safeNumber(v):f.kind==='json'?parseList(key,v):v;}
 if(spec.id==='S20'){const nested={before:{},after:{}};for(const k of ['S','I','N']){nested.before[k]=data['before'+k];nested.after[k]=data['after'+k];}return nested;}return data;}
function addAccount(){const boxes=form.querySelectorAll('[data-account]');if(boxes.length>=50)return;const box=boxes[0].cloneNode(true);accountIndex++;box.querySelector('legend').textContent='Konto '+accountIndex;for(const input of box.querySelectorAll('input')){const old=input.id;input.id=old.replace(/-\d+$/,'')+'-'+accountIndex;input.name=input.id;input.value='';box.querySelector(`label[for="${old}"]`).htmlFor=input.id;}const remove=el('button','Usuń to konto','secondary');remove.type='button';remove.addEventListener('click',()=>{box.remove();invalidate();});box.append(remove);document.querySelector('#accounts').append(box);invalidate();box.querySelector('input').focus();}
function fillInput(data){if(spec.id==='S08'){form.querySelectorAll('[data-account]').forEach((box,i)=>{if(i)box.remove();});accountIndex=1;for(let i=1;i<data.accounts.length;i++)addAccount();[...form.querySelectorAll('[data-account]')].forEach((box,i)=>{for(const input of box.querySelectorAll('input'))input.value=data.accounts[i][input.dataset.field];});}
 else for(const key of spec.fields){let v=spec.id==='S20'?data[key.startsWith('before')?'before':'after'][key.at(-1)]:data[key];const kind=fields[key].kind;if(kind==='json'){v=key==='deposits'?v.map(d=>`${d.month};${d.amountPln}`).join('\n'):key==='rows'?v.map(d=>`${d.date};${d.valuePln};${d.depositPln};${d.withdrawalPln}`).join('\n'):v.join('\n');}form.elements.namedItem(key).value=v??'';}
 invalidate();}
function invalidate(){document.querySelector('#result').hidden=true;document.querySelector('#comparison-result').hidden=true;current=null;}
if(form){form.addEventListener('submit',event=>{event.preventDefault();try{render(execute(spec.tool,readInput()));}catch(e){render({status:'invalid_input',message:e.message});}document.querySelector('#result').focus();});form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);form.addEventListener('reset',()=>{invalidate();baseline=null;announce('');if(spec.id==='S08'){form.querySelectorAll('[data-account]').forEach((b,i)=>{if(i)b.remove();});accountIndex=1;}});document.querySelector('#add-account')?.addEventListener('click',addAccount);
 document.querySelector('#load-example').addEventListener('click',()=>{fillInput(sample);announce('Wczytano hipotetyczny przykład. To nie prognoza ani rekomendacja. Możesz zmienić wszystkie dane.');});
 document.querySelector('#import-plan').addEventListener('click',()=>document.querySelector('#plan-file').click());document.querySelector('#plan-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Plik przekracza limit 1 MB.');const data=JSON.parse(await file.text());if(data.format!=='oki-plan'||data.version!==methodology().calculationVersion||data.calculatorId!==spec.id||data.tool!==spec.tool)throw Error('Plik dotyczy innego kalkulatora lub wersji.');const r=execute(spec.tool,data.input);if(!['ok','insufficient_funds'].includes(r.status))throw Error(r.message??'Niepoprawne dane pliku.');for(const [k,v] of Object.entries(spec.preset))if(data.input[k]!==v)throw Error('Niezgodny tryb planu.');fillInput(data.input);announce('Dane pliku wczytano lokalnie. Sprawdź je przed obliczeniem.');}catch(e){announce('Nie wczytano pliku: '+e.message);}event.target.value='';});
}
for(const button of document.querySelectorAll('[data-print]'))button.addEventListener('click',()=>window.print());
const search=document.querySelector('#search'),cards=[...document.querySelectorAll('[data-filter-list] .card')];let category='';const normalize=s=>s.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').replaceAll('ł','l');
function filter(){const query=normalize(search.value),visible=cards.filter(card=>{const show=(!category||card.dataset.category===category)&&normalize(card.dataset.search).includes(query);card.hidden=!show;return show;});document.querySelector('#filter-status').textContent=visible.length?`Znaleziono: ${visible.length}.`:'Brak wyników. Zmień pytanie lub kategorię.';}
if(search){search.addEventListener('input',filter);for(const chip of document.querySelectorAll('[data-filter]'))chip.addEventListener('click',()=>{category=chip.dataset.filter;for(const b of document.querySelectorAll('[data-filter]')){b.classList.toggle('active',b===chip);b.setAttribute('aria-pressed',String(b===chip));}filter();});}
const reg=await registerTools(document,spec??['get_oki_methodology']);const status=document.querySelector('#webmcp-status');if(status)status.textContent=reg.status==='registered'?'Narzędzia asystenta dostępne na tej stronie.':reg.status==='unavailable'?'Formularze działają samodzielnie; ta przeglądarka nie udostępnia WebMCP.':'Asystent jest niedostępny; formularze działają samodzielnie.';if(reg.dispose)window.addEventListener('pagehide',reg.dispose,{once:true});
